export function buildWindowArticles(previousArtifacts: Record<string, unknown>, cap: number): WindowArticleRow[] {
  const raw = previousArtifacts['articles'];
  const source = Array.isArray(raw) ? raw.filter(isFeedArticleLike) : [];
  const seen = new Set<string>();
  const rows: WindowArticleRow[] = [];
  for (const a of source) {
    if (seen.has(a.article_ref)) continue;
    seen.add(a.article_ref);
    rows.push({
      article_ref: a.article_ref,
      title: a.title ?? '',
      site: a.site ?? '',
      section: a.section ?? '',
      published_at: a.published_at ?? '',
      word_count: typeof a.word_count === 'number' ? a.word_count : 0,
    });
  }
  rows.sort((x, y) => y.published_at.localeCompare(x.published_at));
  return rows.slice(0, Math.max(0, cap));
}

