function affectedThemeLabels(lintResults: unknown): Set<string> {
  const out = new Set<string>();
  if (!Array.isArray(lintResults)) return out;
  for (const raw of lintResults) {
    if (!raw || typeof raw !== 'object') continue;
    const details = (raw as { details?: { affected_theme_labels?: unknown[] } }).details;
    const labels = Array.isArray(details?.affected_theme_labels) ? details.affected_theme_labels : [];
    for (const label of labels) {
      if (typeof label === 'string') out.add(label);
    }
  }
  return out;

